def evaluate(expression: str) -> int | float:
    tokens = _tokenize(expression)
    if not tokens:
        raise ValueError("empty expression")
    pos = [0]

    def parse_expression():
        result = parse_term()
        while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
            op = tokens[pos[0]]
            pos[0] += 1
            right = parse_term()
            if op == '+':
                result = result + right
            else:
                result = result - right
        return result

    def parse_term():
        result = parse_factor()
        while pos[0] < len(tokens) and tokens[pos[0]] in ('*', '/'):
            op = tokens[pos[0]]
            pos[0] += 1
            right = parse_factor()
            if op == '*':
                result = result * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result = result / right
        return result

    def parse_factor():
        if pos[0] < len(tokens) and tokens[pos[0]] == '-':
            pos[0] += 1
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        if pos[0] >= len(tokens):
            raise ValueError("unexpected end of expression")
        tok = tokens[pos[0]]
        if tok == '(':
            pos[0] += 1
            result = parse_expression()
            if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
                raise ValueError("missing closing parenthesis")
            pos[0] += 1
            return result
        if isinstance(tok, (int, float)):
            pos[0] += 1
            return tok
        raise ValueError(f"unexpected token: {tok!r}")

    result = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError(f"unexpected token: {tokens[pos[0]]!r}")
    return result


def _tokenize(expression: str) -> list:
    tokens: list = []
    i = 0
    n = len(expression)
    while i < n:
        c = expression[i]
        if c == ' ':
            i += 1
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            start = i
            has_dot = False
            while i < n and (expression[i].isdigit() or expression[i] == '.'):
                if expression[i] == '.':
                    if has_dot:
                        raise ValueError("invalid number: multiple decimal points")
                    has_dot = True
                i += 1
            num_str = expression[start:i]
            if has_dot:
                if num_str[0] == '.' or num_str[-1] == '.':
                    raise ValueError("invalid number: digits required on both sides of decimal point")
                tokens.append(float(num_str))
            else:
                tokens.append(int(num_str))
        else:
            raise ValueError(f"unknown character: {c!r}")
    return tokens
